REPLACE = {'backend/app.py': {'before': '2b22dc67a03189d165a046ad41cbb751b6f8d5becf46c60bd27894c4814c1c3f', 'after': '"""\nSlick Trace backend — wires slicktrace_core into a real API.\n\nEndpoints are intentionally thin: each reads artifacts already produced by the\npipeline stages rather than re-implementing logic. The time slider is served\nfrom envelope_timeline.json, which the historical-mapping stage writes; nothing\nis simulated per request. Three request-time views remain and are named here:\n/tracks resolves MMSI identity and AIS field quality, /probe reads the forcing\nfile for one point, and /report assembles the committed artifacts with this\nsession\'s query log. This mirrors the masterplan\'s "versioned analysis\nservices" architecture (p.13) — detection, hindcast, candidate replay,\nconfidence checks and forecast stay separate, callable stages.\n\nGROUND-TRUTH DISCIPLINE\n    `truth.json` is never loaded here, and `_strip_truth` removes any field\n    whose name marks it as hidden before anything is serialised. Earlier the\n    manifest endpoint served `true_vessel_key_HIDDEN` and a per-track\n    `is_true_source` flag straight to the browser; the generator no longer\n    writes those, and this is the second line of defence in case a future\n    adapter reintroduces one.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom fastapi import FastAPI, HTTPException, Query\nfrom fastapi.responses import FileResponse, PlainTextResponse\nfrom fastapi.staticfiles import StaticFiles\nfrom pydantic import BaseModel\n\nfrom slicktrace_core.ais_quality import validate_track\nfrom slicktrace_core.identity import parse_mmsi\nfrom slicktrace_core.nlp_query import CaseKB, ask as ask_nlp\nfrom slicktrace_core.report import build_report, render_markdown\nfrom slicktrace_core.case_contract import build_case\n\nREPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nDATA_ROOT = os.path.join(REPO_ROOT, "data", "cases")\n\napp = FastAPI(title="Slick Trace API", version="0.2.0")\n\n_kb_cache: dict[str, CaseKB] = {}\n_query_log: dict[str, list[dict]] = {}\n\n\n# ------------------------------------------------------------ truth guard --\n\ndef _strip_truth(obj):\n    """Remove any dev-only ground-truth field before it reaches a client.\n\n    Belt and braces: the generator no longer writes these, but an adapter for\n    real data could plausibly carry a label column through, and a leak here is\n    silent — the UI would look fine while the answer sat in the network tab.\n    """\n    if isinstance(obj, dict):\n        return {k: _strip_truth(v) for k, v in obj.items()\n                if not (k.endswith("_HIDDEN") or k in ("is_true_source", "true_vessel_key",\n                                                       "absent_true_vessel_key", "roles"))}\n    if isinstance(obj, list):\n        return [_strip_truth(v) for v in obj]\n    return obj\n\n\n# ---------------------------------------------------------------- helpers --\n\ndef _case_dir(incident_id: str) -> str:\n    if "/" in incident_id or "\\\\" in incident_id or incident_id.startswith("."):\n        raise HTTPException(400, "invalid incident id")\n    d = os.path.join(DATA_ROOT, incident_id)\n    if not os.path.isdir(d):\n        raise HTTPException(404, f"incident \'{incident_id}\' not found")\n    return d\n\n\ndef _get_kb(incident_id: str) -> CaseKB:\n    if incident_id not in _kb_cache:\n        _kb_cache[incident_id] = CaseKB(_case_dir(incident_id))\n    return _kb_cache[incident_id]\n\n\ndef _load_json(incident_id: str, fname: str) -> dict | None:\n    path = os.path.join(_case_dir(incident_id), fname)\n    if not os.path.exists(path):\n        return None\n    with open(path) as f:\n        return json.load(f)\n\n\ndef _require(incident_id: str, fname: str, stage: str) -> dict:\n    out = _load_json(incident_id, fname)\n    if out is None:\n        raise HTTPException(404, f"{stage} has not been computed for this incident. "\n                                 f"Run scripts/run_pipeline.py to produce it.")\n    return _strip_truth(out)\n\n\n# ------------------------------------------------------------------ case --\n\n@app.get("/api/incidents/{incident_id}/case")\ndef get_case(incident_id: str):\n    """The whole incident as one validated object (slicktrace_core.case_contract).\n\n    Assembled from the committed artifacts; nothing here computes. A missing\n    optional stage comes back null. An artifact that no longer matches the\n    contract is a 500 naming the mismatch, never a silently partial payload.\n    """\n    case_dir = _case_dir(incident_id)\n    try:\n        case = build_case(case_dir)\n    except FileNotFoundError as e:\n        raise HTTPException(404, f"{e}. Run scripts/run_pipeline.py to produce it.")\n    except ValueError as e:  # includes pydantic\'s ValidationError\n        raise HTTPException(500, f"{incident_id} does not match the Case contract: {e}")\n    return _strip_truth(case.model_dump(mode="json"))\n\n\n@app.get("/api/incidents/{incident_id}/replay-footprints")\ndef get_replay_footprints(incident_id: str):\n    """Each ranked candidate\'s nominal replayed footprint, traced for the map."""\n    return _require(incident_id, "replay_footprints.json", "replay footprints")\n\n\n@app.get("/api/incidents/{incident_id}/forecast-contours")\ndef get_forecast_contours(incident_id: str):\n    """50/75/90% density contours for each forecast horizon, for the map."""\n    return _require(incident_id, "forecast_contours.json", "forecast contours")\n\n\n@app.get("/api/incidents/{incident_id}/track-display")\ndef get_track_display(incident_id: str):\n    """Per-vessel gap windows and a rendering-only smoothed path."""\n    return _require(incident_id, "track_display.json", "track display")\n\n\n@app.get("/api/incidents/{incident_id}/replay-timeline")\ndef get_replay_timeline(incident_id: str):\n    """The named leading candidate\'s scored release, hour by hour, for the map.\n    Empty frames on an abstention: nothing is animated for a vessel not named."""\n    return _require(incident_id, "replay_timeline.json", "replay timeline")\n\n\n@app.get("/api/incidents/{incident_id}/forecast-timeline")\ndef get_forecast_timeline(incident_id: str):\n    """Modelled drift after the image, every hour to +24 h, for the map."""\n    return _require(incident_id, "forecast_timeline.json", "forecast timeline")\n\n\n# ------------------------------------------------------------- incidents --\n\n@app.get("/api/incidents")\ndef list_incidents():\n    if not os.path.isdir(DATA_ROOT):\n        return []\n    out = []\n    for iid in sorted(d for d in os.listdir(DATA_ROOT)\n                      if os.path.isdir(os.path.join(DATA_ROOT, d))):\n        m = _load_json(iid, "manifest.json")\n        if not m:\n            continue\n        at = _load_json(iid, "attribution_result.json") or {}\n        out.append({\n            "incident_id": iid,\n            "acquired_utc": m["acquired_utc"],\n            "provenance_status": m.get("provenance", {}).get("status"),\n            "case_state": m.get("case_state"),\n            "n_vessels": len(m.get("tracks", [])),\n            # family is a property of the case design, not the answer — it says\n            # what kind of test this is, not which vessel did it\n            "family": m.get("generator", {}).get("family"),\n            "outcome": ("unknown_source" if at.get("unknown_source")\n                        else ("named_candidate" if at else None)),\n        })\n    return out\n\n\n@app.get("/api/overview")\ndef get_overview():\n    """Every case with just what its headline finding needs, for the overview grid.\n\n    The fields are copied from attribution_result.json and\n    naive_baseline_result.json - the same ones the Case Finding card reads - so\n    the overview\'s one-line finding is produced by the same rule as the card\'s,\n    not written separately. Nothing here summarises beyond selecting fields.\n    """\n    out = []\n    for row in list_incidents():\n        iid = row["incident_id"]\n        at = _load_json(iid, "attribution_result.json")\n        nb = _load_json(iid, "naive_baseline_result.json")\n        finding = None\n        if at is not None:\n            rk = at.get("ranking") or []\n            top = rk[0] if rk else None\n            near = (nb or {}).get("ranking") or []\n            finding = {\n                "unknown_source": at["unknown_source"],\n                "abstention_iou_gate": at["abstention_iou_gate"],\n                "n_candidates": len(at.get("candidates_considered") or []),\n                "top_candidate_id": at.get("top_candidate_id"),\n                "best": None if top is None else {\n                    "vessel_key": top["vessel_key"], "mean_iou": top["mean_iou"],\n                    "ensemble_win_count": top["ensemble_win_count"], "n_ensemble": top["n_ensemble"]},\n                "runner_up_mean_iou": rk[1]["mean_iou"] if len(rk) > 1 else None,\n                "discrimination": at.get("discrimination"),\n                "nearest": None if not near else {\n                    "vessel_key": near[0]["vessel_key"], "distance_deg": near[0]["distance_deg"]},\n            }\n        out.append({**row, "finding": finding})\n    return out\n\n\n@app.get("/api/incidents/{incident_id}/manifest")\ndef get_manifest(incident_id: str):\n    m = _load_json(incident_id, "manifest.json")\n    if m is None:\n        raise HTTPException(404, "manifest not found")\n    return _strip_truth(m)\n\n\n@app.get("/api/incidents/{incident_id}/scene")\ndef get_scene(incident_id: str):\n    m = _load_json(incident_id, "manifest.json")\n    if m is None:\n        raise HTTPException(404, "manifest not found")\n    path = m["image_path"]\n    if not os.path.isabs(path):\n        path = os.path.join(REPO_ROOT, path)\n    if not os.path.exists(path):\n        raise HTTPException(404, "scene image missing from this case directory")\n    return FileResponse(path, media_type="image/png")\n\n\n@app.get("/api/incidents/{incident_id}/historical-mapping")\ndef get_historical_mapping(incident_id: str):\n    return _require(incident_id, "historical_mapping.json", "historical mapping")\n\n\n@app.get("/api/incidents/{incident_id}/attribution")\ndef get_attribution(incident_id: str):\n    return _require(incident_id, "attribution_result.json", "attribution")\n\n\n@app.get("/api/incidents/{incident_id}/naive-baseline")\ndef get_naive_baseline(incident_id: str):\n    return _require(incident_id, "naive_baseline_result.json", "naive baseline")\n\n\n@app.get("/api/incidents/{incident_id}/detection")\ndef detection(incident_id: str):\n    """Detected slick outline and geometric characterisation (PS part (a))."""\n    return _require(incident_id, "detection_result.json", "detection result")\n\n\n@app.get("/api/incidents/{incident_id}/fragility")\ndef get_fragility(incident_id: str):\n    return _require(incident_id, "fragility_result.json", "rank-fragility analysis")\n\n\n@app.get("/api/incidents/{incident_id}/forecast")\ndef get_forecast(incident_id: str):\n    return _require(incident_id, "forecast_result.json", "forward exposure forecast")\n\n\n@app.get("/api/incidents/{incident_id}/coverage")\ndef get_coverage(incident_id: str):\n    return _require(incident_id, "coverage_result.json", "coverage-aware contact matching")\n\n\n@app.get("/api/incidents/{incident_id}/next-observation")\ndef get_next_observation(incident_id: str):\n    return _require(incident_id, "next_observation_result.json", "next-observation advisor")\n\n\n@app.get("/api/incidents/{incident_id}/tracks")\ndef get_tracks(incident_id: str):\n    m = _load_json(incident_id, "manifest.json")\n    if m is None:\n        raise HTTPException(404, "manifest not found")\n    return _strip_truth({\n        "bbox": m["bbox"],\n        "coastline": m.get("coastline", []),\n        "sensitive_areas": m.get("sensitive_areas", []),\n        # MMSI structure is resolved here rather than in the interface: what a\n        # nine-digit identifier means is a property of the identifier, not of\n        # how it is displayed. Provenance only, never an input to ranking.\n        "tracks": [{"vessel_key": t["vessel_key"], "mmsi": t.get("mmsi"),\n                    "identity": parse_mmsi(t.get("mmsi") or t["vessel_key"]),\n                    "quality": validate_track(t),\n                    "fixes": t["fixes"]} for t in m["tracks"]],\n    })\n\n\n# ------------------------------------------------------- live time slider --\n\n@app.get("/api/geo/coastline")\ndef get_real_coastline():\n    """Real coastline geometry for the scene area, as a reference overlay.\n\n    Natural Earth 10m, public domain, clipped to the case bounding boxes and\n    committed to the repository - not fetched from a tile server. The offline\n    smoke test in docs/evidence is a property this project went out of its way\n    to establish, and a basemap that needs the network would end it.\n\n    The same coastline every case now uses: each manifest carries it clipped\n    to the scene, the detector rejects land against it, and the forecast strands\n    oil on it (slicktrace_core.geography). An invented coastline about 19 km\n    east of this one stood in for it before.\n    """\n    path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),\n                        "data", "geo", "coastline_mumbai.json")\n    if not os.path.exists(path):\n        raise HTTPException(404, "coastline geometry not present")\n    with open(path) as f:\n        geo = json.load(f)\n    return {\n        "geometry": geo,\n        "source": "Natural Earth 10m coastline",\n        "licence": "public domain",\n        "note": ("The coastline every case uses: manifests carry it clipped to the scene, "\n                 "detection rejects land against it and the forecast strands oil on it. "\n                 "Natural Earth 10 m is scene-scale; narrow creeks are resolved only coarsely."),\n    }\n\n\n@app.get("/api/incidents/{incident_id}/dossier.pdf")\ndef get_dossier(incident_id: str):\n    """The investigation report as a PDF, rendered from the committed artifact."""\n    from fastapi.responses import FileResponse\n    path = os.path.join(_case_dir(incident_id), "investigation_dossier.pdf")\n    if not os.path.exists(path):\n        raise HTTPException(404, "dossier not generated for this incident")\n    return FileResponse(path, media_type="application/pdf",\n                        filename=f"{incident_id}_investigation.pdf")\n\n\n@app.get("/api/incidents/{incident_id}/probe")\ndef probe_forcing(incident_id: str,\n                  lon: float = Query(...), lat: float = Query(...),\n                  hours_before: float = Query(0.0, ge=0.0, le=24.0)):\n    """The transport forcing at one point, as the attribution model sees it.\n\n    Deliberately not the true field. The generator applies a spatial swirl the\n    simulator is never given - it is the unmodelled variation the whole\n    fragility analysis exists to probe - and serving it here would leak truth\n    into the interface and make the model look better informed than it is.\n\n    What is returned is the uniform current the attribution actually advects\n    with. A reviewer clicking two points and getting the same answer is seeing\n    a real property of the model, not a broken endpoint.\n    """\n    import math\n    import numpy as np\n\n    m = _load_json(incident_id, "manifest.json")\n    if m is None:\n        raise HTTPException(404, "manifest not found")\n    b = m["bbox"]\n    if not (b["min_lon"] <= lon <= b["max_lon"] and b["min_lat"] <= lat <= b["max_lat"]):\n        raise HTTPException(400, "point is outside the scene")\n\n    f = np.load(m["forcing_path"])\n    # The forcing stores the current in metres per second - the simulator\n    # converts with DEG_PER_MS_HR. An earlier version read these as degrees\n    # per hour and reported a current about 29 times too fast (9.03 kn for a\n    # 0.31 kn current); the bearing was right because the units cancel in it.\n    u_ms, v_ms = float(f["u"]), float(f["v"])\n    east_kmh = u_ms * 3.6\n    north_kmh = v_ms * 3.6\n    speed = math.hypot(east_kmh, north_kmh)\n    bearing = (math.degrees(math.atan2(east_kmh, north_kmh)) + 360) % 360\n\n    return {\n        "incident_id": incident_id,\n        "lon": round(lon, 5), "lat": round(lat, 5),\n        "hours_before_acquisition": hours_before,\n        "current": {\n            "east_km_per_h": round(east_kmh, 3),\n            "north_km_per_h": round(north_kmh, 3),\n            "speed_km_per_h": round(speed, 3),\n            "speed_knots": round(speed / 1.852, 3),\n            "bearing_deg_from_north": round(bearing, 1),\n        },\n        "wind": None,\n        "model_note": (\n            "This is the current the attribution model advects with: uniform in space "\n            "and constant in time. Two different points return the same vector, which "\n            "is a property of the model rather than a fault in this endpoint."\n        ),\n        "truth_note": (\n            "The generator applies a spatial swirl the simulator is never given. That "\n            "unmodelled variation is what the rank-fragility sweep exists to probe, and "\n            "it is deliberately not served here: an interface that showed the true "\n            "field would make the model look better informed than it is."\n        ),\n        "wind_note": (\n            "No wind field exists anywhere in this pipeline - see assumption A17. "\n            "Surface oil moves at roughly 3% of wind speed plus Stokes drift, so this "\n            "is a first-order omission on real data, not a refinement."\n        ),\n    }\n\n\n@app.get("/api/incidents/{incident_id}/envelope")\ndef get_envelope(incident_id: str,\n                 hours_before: float = Query(0.0, ge=0.0, le=24.0),\n                 max_particles: int = Query(300, ge=20, le=600)):\n    """The backward origin envelope at one queried hour, plus every vessel\'s\n    position and membership then.\n\n    Served from envelope_timeline.json, which the historical-mapping stage\n    writes from the same snapshots and membership pass it summarises. Nothing\n    is simulated here: the frame nearest the requested time is returned, so the\n    slider shows exactly the 25 hourly states the pipeline computed and the\n    determinism check covers.\n    """\n    tl = _require(incident_id, "envelope_timeline.json", "envelope timeline")\n    frame = min(tl["frames"], key=lambda f: abs(f["hours_before_acquisition"] - hours_before))\n    step = max(1, len(frame["particles"]) // max_particles)\n    return {\n        "incident_id": incident_id,\n        "hours_before_acquisition": frame["hours_before_acquisition"],\n        "time_utc": frame["time_utc"],\n        "acquired_utc": tl["acquired_utc"],\n        "layer_status": frame["layer_status"],\n        "hindcast": frame["hindcast"],\n        "inclusion_radius_deg": tl["inclusion_radius_deg"],\n        "particles": frame["particles"][::step],\n        # Contours were computed on the full particle set, not the decimated one\n        # sent to the client: subsampling for bandwidth does not move the mass.\n        "density_contours": frame["density_contours"],\n        "density_note": tl["density_note"],\n        "vessels": frame["vessels"],\n        "note": tl["note"],\n    }\n\n\n@app.get("/api/incidents/{incident_id}/envelope-timeline")\ndef get_envelope_timeline(incident_id: str):\n    """All 25 hourly frames at once, so an interface can scrub without a\n    request per step."""\n    return _require(incident_id, "envelope_timeline.json", "envelope timeline")\n\n\n# ------------------------------------------------------------------- ask --\n\nclass AskRequest(BaseModel):\n    question: str\n\n\n@app.post("/api/incidents/{incident_id}/ask")\ndef post_ask(incident_id: str, req: AskRequest):\n    _case_dir(incident_id)\n    kb = _get_kb(incident_id)\n    result = ask_nlp(kb, req.question)\n    payload = {\n        "question": result.question,\n        "intent": result.intent,\n        "supported": result.supported,\n        "filters": result.filters,\n        "answer": result.answer,\n        "citations": result.citations,\n    }\n    _query_log.setdefault(incident_id, []).append(payload)\n    return payload\n\n\n# ---------------------------------------------------------------- export --\n\n@app.get("/api/incidents/{incident_id}/report")\ndef get_report(incident_id: str):\n    case_dir = _case_dir(incident_id)\n    return _strip_truth(build_report(case_dir, _query_log.get(incident_id, [])))\n\n\n@app.get("/api/incidents/{incident_id}/report.md", response_class=PlainTextResponse)\ndef get_report_markdown(incident_id: str):\n    case_dir = _case_dir(incident_id)\n    report = _strip_truth(build_report(case_dir, _query_log.get(incident_id, [])))\n    return PlainTextResponse(\n        render_markdown(report), media_type="text/markdown",\n        headers={"Content-Disposition":\n                 f\'attachment; filename="{incident_id}_investigation_report.md"\'})\n\n\n@app.get("/api/health")\ndef health():\n    return {"status": "ok"}\n\n\n@app.get("/api/version")\ndef version():\n    return {\n        "api_version": app.version,\n        "compute_profile": "cpu",\n        "outbound_calls_at_runtime": "none — no model API, no tile server, no font CDN",\n    }\n\n\n# Serve the built frontend (if present) at the root, so the whole app is one\n# process — required for the single-container Docker packaging.\n_frontend_dist = os.path.join(REPO_ROOT, "frontend", "dist")\nif os.path.isdir(_frontend_dist):\n    app.mount("/", StaticFiles(directory=_frontend_dist, html=True), name="frontend")\n'}, 'frontend/src/App.jsx': {'before': 'b3706fdb5504a1c8d97d48cfc540dc2f9a8919a348f37b88b6e9f45c885dda2a', 'after': 'import { Suspense, lazy, useCallback, useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport Overview from \'./Overview\';\nimport { attachStickyHeaders } from \'./stickyHeaders\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport RankingRevealCard from \'./cards/RankingRevealCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\n// loaded only when a tour starts, so driver.js is not in every page view\nconst Tour = lazy(() => import(\'./tour/Tour\'));\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  // Routes live in the URL hash, so Back and Forward work: #/overview (the\n  // default) or #/case/<id>. The last case opened stays loaded behind the\n  // overview, so returning to it is instant.\n  const parseRoute = () => {\n    const m = window.location.hash.match(/^#\\/case\\/([\\w-]+)/);\n    return m ? { view: \'case\', id: m[1] } : { view: \'overview\', id: null };\n  };\n  const [route, setRoute] = useState(parseRoute);\n  useEffect(() => {\n    const on = () => setRoute(parseRoute());\n    window.addEventListener(\'hashchange\', on);\n    return () => window.removeEventListener(\'hashchange\', on);\n  }, []);\n  const [lastCase, setLastCase] = useState(route.id ?? \'case_0001\');\n  if (route.id && route.id !== lastCase) setLastCase(route.id);\n  const incidentId = route.id ?? lastCase;\n  const openCase = useCallback((id) => { window.location.hash = `#/case/${id}`; }, []);\n  const openOverview = useCallback(() => { window.location.hash = \'#/overview\'; }, []);\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n\n\n  const [touring, setTouring] = useState(false);\n\n  // Cross-fade between cases: the last fully loaded case stays on screen (dimmed)\n  // until the next has loaded, then fades in - rather than blanking and\n  // reloading. Updated during render, the standard pattern for derived state.\n  const [shown, setShown] = useState(null);\n  if (c && (shown?.c !== c || shown?.report !== report || shown?.tracks !== tracks)) {\n    setShown({ id: incidentId, c, report, tracks });\n  }\n  const vid = shown?.id;\n  const vc = shown?.c;\n  const leaving = !!shown && shown.id !== incidentId;\n  const meta = vc?.meta;\n\n  // scroll-edge effect on the pinned card headers; the column remounts per case\n  useEffect(() => attachStickyHeaders(document.querySelector(\'.finder-features\')), [vid, route.view]);\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && route.view === \'case\' && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          <button type="button" className={`tour-btn${touring ? \' is-on\' : \'\'}`} onClick={() => setTouring((t) => !t)}>\n            {touring ? \'Exit Tour\' : \'Start Tour\'}\n          </button>\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n      {touring && incidents.length > 0 && (\n        <Suspense fallback={null}>\n          <Tour incidents={incidents} api={api} selectCase={openCase} onExit={() => setTouring(false)} />\n        </Suspense>\n      )}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <button type="button" className={`nav-overview${route.view === \'overview\' ? \' is-active\' : \'\'}`} onClick={openOverview}>\n            <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 2h5v5H2zM9 2h5v5H9zM2 9h5v5H2zM9 9h5v5H9z" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" /></svg>\n            Overview\n          </button>\n          <CaseSwitcher incidents={incidents} active={route.view === \'case\' ? incidentId : null} onSelect={openCase} />\n        </aside>\n\n        {route.view === \'overview\' ? <Overview api={api} onOpen={openCase} /> : (\n        <div className={`finder-content${leaving ? \' is-leaving\' : \'\'}`} data-case={vid}>\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={vid}>\n            {vc && (\n              <>\n                <CaseFindingCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <RankingRevealCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <ObservedSceneCard meta={meta} slick={vc.slick} sceneUrl={api.sceneUrl(vid)}\n                                   nVessels={vc.vessels.length} />\n                <HistoricalReplayCard incidentId={vid} api={api} c={vc} tracks={shown.tracks} />\n                <FragilityCard fragility={vc.fragility} />\n                <ForecastCard forecast={vc.forecast} />\n                <NextObservationCard nextObs={vc.next_observation} />\n                <CoverageCard coverage={vc.coverage} />\n                <ProvenanceCard meta={meta} report={shown.report} />\n              </>\n            )}\n          </div>\n\n          <div className="finder-details" key={`d-${vid}`}>\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(vid)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(vid)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            {vc && (\n              <ConclusionGraph key={vid} attribution={vc.attribution} naive={vc.baseline}\n                               report={shown.report} detection={vc.slick} fragility={vc.fragility} />\n            )}\n            {vid && <AskSlickTraceCard key={`ask-${vid}`} incidentId={vid} api={api} />}\n          </div>\n        </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'}, 'frontend/src/CaseSwitcher.jsx': {'before': 'd3b4fe51ce5813d53cdc1e4d149880ebafd7e227b536b6463188c10b5bf8f165', 'after': 'import { useLayoutEffect, useRef, useState } from \'react\';\nimport { FAMILY_LABEL } from \'./families\';\n\n/**\n * Case switcher across the full generated benchmark.\n *\n * Showing one case invites the cherry-picking objection and cannot answer it.\n * Every case is reachable here, labelled with its family and its outcome, so\n * a reviewer can go straight to the absent-source cases and watch the system\n * decline to name anyone.\n *\n * The selection is one element that travels to the active row, as in a macOS\n * source list, rather than each row swapping its own colour. It is measured\n * from the row itself, so it follows any change in row height or font size.\n */\n\n\nexport default function CaseSwitcher({ incidents, active, onSelect }) {\n  const wrapRef = useRef(null);\n  const rowRefs = useRef({});\n  const [box, setBox] = useState(null);\n  const [ready, setReady] = useState(false);\n\n  useLayoutEffect(() => {\n    const measure = () => {\n      const row = rowRefs.current[active];\n      if (!row || !wrapRef.current) return;\n      setBox({ y: row.offsetTop, h: row.offsetHeight });\n    };\n    measure();\n    // Enable the slide only after the first placement, so the selection does\n    // not travel in from the top on load.\n    const id = requestAnimationFrame(() => setReady(true));\n    const ro = typeof ResizeObserver !== \'undefined\' ? new ResizeObserver(measure) : null;\n    if (ro && wrapRef.current) ro.observe(wrapRef.current);\n    return () => { cancelAnimationFrame(id); ro?.disconnect(); };\n  }, [active, incidents]);\n\n  if (!incidents?.length) return null;\n\n  return (\n    <nav className="case-switcher" aria-label="Incident cases">\n      <span className="case-switcher-label">\n        Cases\n      </span>\n      <div className="case-list-wrap" ref={wrapRef}>\n        <span\n          className={`case-highlight${ready && box ? \' is-ready\' : \'\'}`}\n          style={box ? { \'--y\': `${box.y}px`, \'--h\': `${box.h}px` } : undefined}\n          aria-hidden="true"\n        />\n        <ul className="case-list">\n          {incidents.map((c) => {\n            const unknown = c.outcome === \'unknown_source\';\n            const isActive = c.incident_id === active;\n            return (\n              <li key={c.incident_id}>\n                <button\n                  ref={(el) => { rowRefs.current[c.incident_id] = el; }}\n                  type="button"\n                  className={`case-item${isActive ? \' is-active\' : \'\'}`}\n                  aria-current={isActive ? \'true\' : undefined}\n                  onClick={() => onSelect(c.incident_id)}\n                >\n                  <span\n                    className={`case-indicator ${unknown ? \'indicator-unknown\' : \'indicator-known\'}`}\n                    aria-hidden="true"\n                  />\n                  <span className="case-text">\n                    <span className="case-id">{c.incident_id.replace(\'case_\', \'case \')}</span>\n                    <span className="case-description">\n                      {FAMILY_LABEL[c.family] ?? c.family}\n                    </span>\n                  </span>\n                  <span className="visually-hidden">\n                    {unknown ? \', outcome: source not identified\' : \', outcome: source identified\'}\n                  </span>\n                </button>\n              </li>\n            );\n          })}\n        </ul>\n      </div>\n    </nav>\n  );\n}\n'}, 'frontend/src/api.js': {'before': 'b63e7d2f0da6b5a8fd0fe904d1785608c808c2f8b170d2eca0fb471c528a339b', 'after': "const BASE = '/api';\n\nasync function j(path, opts) {\n  const res = await fetch(BASE + path, opts);\n  if (!res.ok) {\n    const detail = await res.text();\n    throw new Error(`${res.status} ${path}: ${detail}`);\n  }\n  return res.json();\n}\n\nexport const api = {\n  listIncidents: () => j('/incidents'),\n  // the whole incident as one validated object (slicktrace_core.case_contract)\n  case: (id) => j(`/incidents/${id}/case`),\n  manifest: (id) => j(`/incidents/${id}/manifest`),\n  sceneUrl: (id) => `${BASE}/incidents/${id}/scene`,\n  historicalMapping: (id) => j(`/incidents/${id}/historical-mapping`),\n  attribution: (id) => j(`/incidents/${id}/attribution`),\n  naiveBaseline: (id) => j(`/incidents/${id}/naive-baseline`),\n  tracks: (id) => j(`/incidents/${id}/tracks`),\n  overview: () => j('/overview'),\n  // computed frames for the replay map's time slider\n  envelopeTimeline: (id) => j(`/incidents/${id}/envelope-timeline`),\n  replayTimeline: (id) => j(`/incidents/${id}/replay-timeline`),\n  forecastTimeline: (id) => j(`/incidents/${id}/forecast-timeline`),\n  trackDisplay: (id) => j(`/incidents/${id}/track-display`),\n  detection: (id) => j(`/incidents/${id}/detection`),\n  fragility: (id) => j(`/incidents/${id}/fragility`),\n  forecast: (id) => j(`/incidents/${id}/forecast`),\n  coverage: (id) => j(`/incidents/${id}/coverage`),\n  nextObservation: (id) => j(`/incidents/${id}/next-observation`),\n  report: (id) => j(`/incidents/${id}/report`),\n  reportUrl: (id) => `${BASE}/incidents/${id}/report.md`,\n  dossierUrl: (id) => `${BASE}/incidents/${id}/dossier.pdf`,\n  realCoastline: () => j('/geo/coastline'),\n  // hours_before is the slider position: 0 = acquisition time, 24 = a full day back\n  probe: (id, lon, lat, hoursBefore) =>\n    j(`/incidents/${id}/probe?lon=${lon}&lat=${lat}`\n      + `&hours_before=${encodeURIComponent(hoursBefore)}`),\n\n  envelope: (id, hoursBefore) =>\n    j(`/incidents/${id}/envelope?hours_before=${encodeURIComponent(hoursBefore)}`),\n  ask: (id, question) => j(`/incidents/${id}/ask`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ question }),\n  }),\n};\n"}, 'frontend/src/cards/CaseFindingCard.jsx': {'before': '45658c57f90128c1e6bfc05ca35d450a93f57c9519be909a046419e5328f62f3', 'after': 'import { Badge, Card, Stat } from \'../ui/primitives\';\nimport { findingHeadline } from \'../findingText\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * The finding, stated before the evidence.\n *\n * Wording stays neutral: the proximity pick is "not supported by forward\n * replay", never "wrong" or struck through, because the interface has no\n * ground truth to call anything wrong. On an abstention it says so plainly.\n */\nexport default function CaseFindingCard({ attribution, baseline, vessels }) {\n  if (!attribution || !baseline) return null;\n\n  const nearest = baseline.ranking[0];\n  const top = attribution.ranking[0];\n  const runnerUp = attribution.ranking[1];\n  const unknown = attribution.unknown_source;\n  const nCandidates = attribution.candidates_considered.length;\n  const disc = attribution.discrimination;\n  const topVessel = vessels?.find((v) => v.vessel_key === top?.vessel_key);\n  const differs = !unknown && nearest && top && nearest.vessel_key !== top.vessel_key;\n\n  const gate = attribution.abstention_iou_gate;\n  const badge = unknown\n    ? <Badge tone="warning">System abstains</Badge>\n    : <Badge tone="accent">{differs ? \'Nearest vessel not supported\' : \'Candidate named\'}</Badge>;\n\n  return (\n    <Card title="Case Finding" badge={badge} className={`finding${unknown ? \' is-abstain\' : \'\'}`}>\n      {unknown && (\n        // A deliberate outcome, drawn as one: the statement, and every candidate\'s fit\n        // against the gate, so it is visible that none reaches it. Keyed on the\n        // system\'s own output (unknown_source), never on the case\'s family.\n        <div className="abstain-block" role="status">\n          <div className="abstain-head">\n            <svg className="abstain-mark" viewBox="0 0 20 20" aria-hidden="true">\n              <circle cx="10" cy="10" r="8" /><path d="M5.5 10h9" />\n            </svg>\n            <span>\n              <strong>The system abstains</strong>\n              <em>No candidate\'s replayed release meets the fit gate, so no vessel is named.</em>\n            </span>\n          </div>\n          <div className="gate-meter" aria-label={`Mean IoU of each replayed candidate against the fit gate of ${gate}`}>\n            <div className="gate-track">\n              <span className="gate-zone" style={{ left: `${gate * 100}%` }}><i>would be named</i></span>\n              <span className="gate-tick" style={{ left: `${gate * 100}%` }} />\n              {attribution.ranking.map((r) => (\n                <span key={r.vessel_key} className={`gate-dot${r === top ? \' is-best\' : \'\'}`}\n                      style={{ left: `${Math.max(0, Math.min(1, r.mean_iou)) * 100}%` }}\n                      title={`${r.vessel_key}: mean IoU ${r.mean_iou.toFixed(3)}`} />\n              ))}\n            </div>\n            <div className="gate-scale">\n              <span style={{ left: 0 }}>0</span>\n              <span className="is-gate" style={{ left: `${gate * 100}%` }}>gate {gate}</span>\n              <span style={{ left: \'100%\' }}>1</span>\n            </div>\n            <p className="gate-caption">\n              {attribution.ranking.length} candidate{attribution.ranking.length === 1 ? \'\' : \'s\'} replayed; the best reaches a\n              mean IoU of {top?.mean_iou.toFixed(3) ?? \'—\'}.\n            </p>\n          </div>\n        </div>\n      )}\n      <p className="finding-line">{findingHeadline({ unknown, nCandidates, differs })}</p>\n\n      <div className="finding-compare">\n        <div className={`finding-side${differs || unknown ? \' is-muted\' : \'\'}`}>\n          <div className="finding-side-label">Proximity baseline picks</div>\n          <Stat mono label="Nearest at image time" value={nearest?.vessel_key}\n                caption={`${nearest?.distance_deg.toFixed(3)}° from the slick. ${C.distance}`} />\n        </div>\n        <span className="finding-arrow" aria-hidden="true">→</span>\n        <div className="finding-side">\n          <div className="finding-side-label">Forward replay</div>\n          {unknown ? (\n            <Stat label="No vessel named" value={`best fit ${top?.mean_iou.toFixed(3) ?? \'—\'}`}\n                  caption={`Below the gate of ${gate}. ${C.fitGate}`} />\n          ) : (\n            <Stat mono label="Best physical fit" value={top?.vessel_key}\n                  caption={`Mean IoU ${top?.mean_iou.toFixed(3)}${runnerUp ? ` against ${runnerUp.mean_iou.toFixed(3)} for the runner-up` : \'\'}. ${C.meanIou}`} />\n          )}\n        </div>\n      </div>\n\n      {!unknown && topVessel?.first_entry_hours_before != null && (\n        <p className="card-caption" style={{ marginTop: \'var(--space-3)\', marginBottom: 0 }}>\n          Inside the origin area {topVessel.first_entry_hours_before} h before the image. {C.firstEntry}\n        </p>\n      )}\n      {!unknown && disc?.discriminated === false && (\n        <p className="card-caption" style={{ marginTop: \'var(--space-2)\', marginBottom: 0 }}>\n          The top two are not separated: loss gap {disc.loss_gap}, under {disc.tolerance}. {C.lossGap}\n        </p>\n      )}\n\n      <p className="finding-note">\n        {unknown\n          ? \'Declining is what the system does when no candidate’s replayed release fits the slick well enough. The source may be outside the data — for example, a vessel that left the scene before the image.\'\n          : \'A ranking reflects physical consistency under tested assumptions: an investigative lead, not proof of responsibility.\'}\n      </p>\n    </Card>\n  );\n}\n'}, 'scripts/verify_document_claims.py': {'before': 'f6e2c483c330801535fb27b3826edcce063075425fbbd274aa9013aa804b8769', 'after': '"""Check every factual claim in the project document against the repository."""\nimport json, glob, os, subprocess, sys\n\nok, bad = [], []\ndef check(label, got, want, tol=None):\n    if tol is not None:\n        good = got is not None and abs(got - want) <= tol\n    else:\n        good = got == want\n    (ok if good else bad).append(f"{label}: got {got!r}, doc says {want!r}")\n\nV = json.load(open("docs/validation_report.json"))\nsp, sa = V["attribution"]["source_present"], V["attribution"]["source_absent"]\n\ncheck("source-present n",        sp["n"], 7)\ncheck("method top-1",            sp["method_top1"], 7)\ncheck("naive top-1",             sp["naive_top1"], 0)\ncheck("McNemar p",               sp["mcnemar"]["p_value"], 0.0156, 1e-6)\ncheck("source-absent n",         sa["n"], 2)\ncheck("correct abstentions",     sa["correct_abstentions"], 1)\ncheck("false named",             sa["false_named_attributions"], 1)\ncheck("NLP total",               V["nlp"]["n"], 47)\ncheck("NLP passed",              V["nlp"]["n_pass"], 47)\ncheck("NLP refusals",            V["nlp"]["n_refusal"], 12)\ncheck("leak audit rules flagged", sum(r["flagged"] for r in V["leak_audit"]["rules"]), 3)\ncheck("no rule near 7/7",        max(r["hits"] for r in V["leak_audit"]["rules"]) < 6, True)\n\nd = V["detection"]\ncheck("classical val IoU",       round(d["baseline_val"]["iou_on_oil"],3), 0.857, 0.002)\ncheck("classical val recall",    round(d["baseline_val"]["recall_on_oil"],3), 0.860, 0.002)\ncheck("classical test IoU",      round(d["baseline_test"]["iou_on_oil"],3), 0.814, 0.002)\ncheck("classical test recall",   round(d["baseline_test"]["recall_on_oil"],3), 0.819, 0.002)\ncheck("classical val FP look",   d["baseline_val"]["false_positive_rate_lookalike"], 0.0)\ncheck("classical test FP look",  d["baseline_test"]["false_positive_rate_lookalike"], 0.0)\n\nu = d.get("unet")\nif u and "val" in u:\n    check("U-Net val IoU",       round(u["val"]["iou_on_oil"],3), 0.970, 0.002)\n    check("U-Net val recall",    round(u["val"]["recall_on_oil"],3), 0.994, 0.002)\n    check("U-Net test IoU",      round(u["test"]["iou_on_oil"],3), 0.968, 0.002)\n    check("U-Net test recall",   round(u["test"]["recall_on_oil"],3), 0.998, 0.002)\nelse:\n    bad.append("U-Net eval missing from validation_report.json")\n\ncases = sorted(glob.glob("data/cases/case_*"))\ncheck("case count", len(cases), 9)\n\nious = []\nfor c in cases:\n    g = json.load(open(f"{c}/detection_result.json"))\n    ious.append(g["agreement_with_truth_mask"]["iou"])\ncheck("min scene IoU >= 0.95", min(ious) >= 0.95, True)\ncheck("max scene IoU <= 0.99", max(ious) <= 0.99, True)\n\ncheck("assumptions",\n      int(subprocess.run("grep -c \'^### A\' docs/assumptions_register.md",\n          shell=True, capture_output=True, text=True).stdout.strip()), 24)\n\nt = subprocess.run("python3 -m pytest tests/ -q 2>&1 | tail -2",\n                   shell=True, capture_output=True, text=True).stdout\ncheck("338 tests pass", "338 passed" in t, True)\n\nfor f in ("data/geo/coastline_mumbai.json", "data/detection/unet.pt",\n          "slicktrace_core/adapters/marinecadastre.py",\n          "slicktrace_core/adapters/geotiff.py", "slicktrace_core/radiometry.py",\n          "slicktrace_core/tiling.py", "slicktrace_core/speckle.py",\n          "slicktrace_core/dossier.py", "docs/calibration_report.md",\n          ".github/workflows/tests.yml"):\n    check(f"exists {f}", os.path.exists(f), True)\n\nfams = set()\nfor c in cases:\n    fams.add(json.load(open(f"{c}/truth.json"))["family"])\ncheck("five families", len(fams), 5)\n\nprint(f"\\n{\'=\'*60}\\nPASSED {len(ok)}   FAILED {len(bad)}\\n{\'=\'*60}")\nfor b in bad:\n    print("  MISMATCH:", b)\nif not bad:\n    print("  every claim in the document matches the repository")\n'}, 'tests/test_api_and_suite.py': {'before': 'ba860c22966cce42f1a2e7f7ff558050d8db9401e4ea78ea0ab323b35145ad30', 'after': '"""API surface tests and the frozen NLP suite as a pass/fail gate."""\n\nfrom __future__ import annotations\n\nimport json\nimport os\n\nimport pytest\nfrom fastapi.testclient import TestClient\n\nfrom backend.app import app\nfrom tests.nlp_suite import resolve_suite\nfrom slicktrace_core.nlp_query import CaseKB, ask\n\nclient = TestClient(app)\nCASE = "case_0001"\nCASE_DIR = os.path.join("data", "cases", CASE)\n\n\n# ------------------------------------------------------------ NLP suite ---\n\ndef _suite():\n    kb = CaseKB(CASE_DIR)\n    ranked = [r["vessel_key"] for r in (kb.attribution or {}).get("ranking", [])]\n    # filtered out before ranking: excluded or unassessed (see run_validation.py)\n    excluded = [a["vessel_key"] for a in (kb.historical_mapping or {}).get("assessments", [])\n                if a["status"] != "candidate"]\n    return kb, resolve_suite(list(kb.tracks_by_key), ranked, excluded)\n\n\ndef test_nlp_suite_has_enough_questions_and_enough_refusals():\n    """Masterplan p.15 asks for at least 30 questions across supported intents,\n    paraphrases and ambiguous/unsupported cases."""\n    _kb, suite = _suite()\n    assert len(suite) >= 30, f"suite has only {len(suite)} questions"\n    refusals = [q for q in suite if not q["expect_supported"]]\n    assert len(refusals) >= 8, (\n        "too few refusal cases — a suite of answerable questions measures coverage, "\n        "not grounding")\n\n\n@pytest.mark.parametrize("item", _suite()[1], ids=lambda i: i["question"][:48])\ndef test_nlp_suite_item(item):\n    kb = CaseKB(CASE_DIR)\n    result = ask(kb, item["question"])\n    assert result.intent == item["expect_intent"], (\n        f"intent mismatch for {item[\'question\']!r}")\n    assert result.supported == item["expect_supported"], (\n        f"support mismatch for {item[\'question\']!r}: {result.answer}")\n    if result.supported and item.get("expect_citations", True):\n        assert result.citations, f"uncited answer for {item[\'question\']!r}"\n\n\n# ------------------------------------------------------------------ API ---\n\ndef test_health_and_version():\n    assert client.get("/api/health").json()["status"] == "ok"\n    v = client.get("/api/version").json()\n    assert v["compute_profile"] == "cpu"\n\n\ndef test_incident_list_shape():\n    incidents = client.get("/api/incidents").json()\n    assert len(incidents) >= 4, "at least four independently generated cases must exist"\n    families = {i["family"] for i in incidents}\n    for required in ("decoy", "moving_discharge", "absent_source"):\n        assert required in families, f"no {required} case present"\n\n\n@pytest.mark.parametrize("path", [\n    "manifest", "scene", "historical-mapping", "attribution", "naive-baseline",\n    "tracks", "fragility", "forecast", "coverage", "next-observation",\n    "report", "report.md",\n])\ndef test_endpoint_responds(path):\n    resp = client.get(f"/api/incidents/{CASE}/{path}")\n    assert resp.status_code == 200, f"{path} -> {resp.status_code}"\n\n\ndef test_unknown_incident_is_404_not_500():\n    assert client.get("/api/incidents/does_not_exist/manifest").status_code == 404\n\n\ndef test_path_traversal_rejected():\n    resp = client.get("/api/incidents/..%2F..%2Fetc/manifest")\n    assert resp.status_code in (400, 404)\n\n\ndef test_envelope_slider_is_live_and_time_varying():\n    """The UTC control must be a live query, not a pre-rendered filmstrip:\n    different requested times must return different envelope states."""\n    a = client.get(f"/api/incidents/{CASE}/envelope?hours_before=0").json()\n    b = client.get(f"/api/incidents/{CASE}/envelope?hours_before=12").json()\n    assert a["time_utc"] != b["time_utc"]\n    assert a["particles"] != b["particles"]\n    assert a["layer_status"] == "observed" and a["hindcast"] is False\n    assert b["layer_status"] == "modelled" and b["hindcast"] is True\n\n\ndef test_envelope_reports_per_time_membership():\n    """Candidates must be able to enter and leave the envelope as time moves —\n    that transition is the demonstration, not a static label."""\n    states = set()\n    for h in range(0, 25, 2):\n        env = client.get(f"/api/incidents/{CASE}/envelope?hours_before={h}").json()\n        for v in env["vessels"]:\n            states.add(v["at_this_time"])\n    assert "inside" in states and "outside" in states, (\n        "no vessel ever changes envelope membership across the window")\n\n\ndef test_envelope_rejects_out_of_range_time():\n    assert client.get(f"/api/incidents/{CASE}/envelope?hours_before=999").status_code == 422\n\n\ndef test_envelope_timeline_agrees_with_historical_mapping():\n    """The replay and the historical filtering come from one membership pass:\n    every frame\'s per-vessel state must equal that vessel\'s hourly_state."""\n    for cid in sorted(os.listdir(os.path.join("data", "cases"))):\n        case_dir = os.path.join("data", "cases", cid)\n        with open(os.path.join(case_dir, "envelope_timeline.json")) as f:\n            tl = json.load(f)\n        with open(os.path.join(case_dir, "historical_mapping.json")) as f:\n            hm = json.load(f)\n        assert [fr["hours_before_acquisition"] for fr in tl["frames"]] == hm["hours_queried"]\n        assert tl["inclusion_radius_deg"] == hm["inclusion_radius_deg"]\n        by_key = {a["vessel_key"]: a for a in hm["assessments"]}\n        for i, frame in enumerate(tl["frames"]):\n            for v in frame["vessels"]:\n                a = by_key[v["vessel_key"]]\n                assert v["at_this_time"] == a["hourly_state"][i], (cid, v["vessel_key"], i)\n                assert v["overall_status"] == a["status"]\n\n\ndef test_envelope_endpoints_do_not_simulate_at_request_time(monkeypatch):\n    """Serving the replay, or answering a time-window question, must not rerun\n    the backward simulation, the membership pass or the density estimate."""\n    import backend.app as api_module\n    import slicktrace_core.envelope_density as density_module\n    import slicktrace_core.hindcast as hindcast_module\n    import slicktrace_core.nlp_query as nlp_module\n\n    def refuse(*_args, **_kwargs):\n        raise AssertionError("simulation at request time")\n\n    for mod in (hindcast_module, api_module, nlp_module):\n        for name in ("build_backward_envelope", "vessel_hourly_states", "assess_vessels"):\n            monkeypatch.setattr(mod, name, refuse, raising=False)\n    for mod in (density_module, api_module, nlp_module):\n        monkeypatch.setattr(mod, "density_contours", refuse, raising=False)\n\n    timeline = client.get(f"/api/incidents/{CASE}/envelope-timeline").json()\n    assert len(timeline["frames"]) == 25\n    for h in (0, 7, 24):\n        resp = client.get(f"/api/incidents/{CASE}/envelope?hours_before={h}")\n        assert resp.status_code == 200\n        assert resp.json()["time_utc"] == timeline["frames"][h]["time_utc"]\n    answer = client.post(f"/api/incidents/{CASE}/ask", json={\n        "question": "Which vessels crossed the likely origin zone from 02:00 to 05:00 UTC?"}).json()\n    assert answer["supported"] and "hourly_state" in answer["citations"][0]\n\n\ndef test_ask_endpoint_returns_filters_and_citations():\n    resp = client.post(f"/api/incidents/{CASE}/ask",\n                       json={"question": "What is the top candidate and why?"})\n    body = resp.json()\n    assert body["supported"] is True\n    assert body["citations"]\n\n\ndef test_ask_endpoint_refuses_visibly():\n    resp = client.post(f"/api/incidents/{CASE}/ask",\n                       json={"question": "Write me a press release about this spill."})\n    body = resp.json()\n    assert body["supported"] is False\n    assert body["intent"] == "unsupported"\n\n\ndef test_report_markdown_states_its_limits():\n    text = client.get(f"/api/incidents/{CASE}/report.md").text\n    assert "not a court-ready dossier" in text.lower()\n    assert "not a legal finding" in text.lower()\n    assert "sha-256" in text.lower()\n\n\ndef test_report_for_absent_source_case_says_unknown_source():\n    """Every absent-source case that abstains says so in its report. The one\n    that does not (tests/test_invariants.py, KNOWN_FALSE_NAMINGS) must not."""\n    absent = [i["incident_id"] for i in client.get("/api/incidents").json()\n              if i["family"] == "absent_source"]\n    assert absent\n    for cid in absent:\n        abstained = client.get(f"/api/incidents/{cid}/attribution").json()["unknown_source"]\n        text = client.get(f"/api/incidents/{cid}/report.md").text\n        assert ("Unknown source" in text) == abstained, cid\n\n\ndef test_missing_stage_returns_actionable_404(tmp_path):\n    """A missing artifact should say what to run, not fail opaquely."""\n    empty = os.path.join("data", "cases", "_tmp_empty_case")\n    os.makedirs(empty, exist_ok=True)\n    try:\n        with open(os.path.join(empty, "manifest.json"), "w") as f:\n            json.dump({"incident_id": "_tmp_empty_case", "acquired_utc": "2026-09-10T04:30:00+00:00",\n                       "bbox": {"min_lon": 0, "min_lat": 0, "max_lon": 1, "max_lat": 1},\n                       "tracks": [], "image_path": "missing.png"}, f)\n        resp = client.get("/api/incidents/_tmp_empty_case/attribution")\n        assert resp.status_code == 404\n        assert "run_pipeline" in resp.json()["detail"]\n    finally:\n        import shutil\n        shutil.rmtree(empty, ignore_errors=True)\n\n\n# ------------------------------------------------------------------ case --\n\ndef test_case_endpoint_serves_the_contract_for_every_case():\n    from slicktrace_core.case_contract import Case, build_case\n    ids = [i["incident_id"] for i in client.get("/api/incidents").json()]\n    assert len(ids) == 9\n    for iid in ids:\n        resp = client.get(f"/api/incidents/{iid}/case")\n        assert resp.status_code == 200, iid\n        Case.model_validate(resp.json())\n        assert resp.json() == build_case(os.path.join("data", "cases", iid)).model_dump(mode="json")\n\n\ndef test_case_endpoint_sections_equal_the_per_stage_endpoints():\n    """Verbatim means verbatim: each section is byte-for-byte what its own\n    endpoint already serves."""\n    case = client.get(f"/api/incidents/{CASE}/case").json()\n    for section, path in (("baseline", "naive-baseline"), ("attribution", "attribution"),\n                          ("fragility", "fragility"), ("coverage", "coverage"),\n                          ("forecast", "forecast"), ("next_observation", "next-observation")):\n        assert case[section] == client.get(f"/api/incidents/{CASE}/{path}").json(), section\n\n\ndef test_case_endpoint_missing_stage_returns_actionable_404():\n    empty = os.path.join("data", "cases", "_tmp_case_only_manifest")\n    os.makedirs(empty, exist_ok=True)\n    try:\n        with open(os.path.join(empty, "manifest.json"), "w") as f:\n            json.dump({"incident_id": "_tmp_case_only_manifest", "tracks": []}, f)\n        resp = client.get("/api/incidents/_tmp_case_only_manifest/case")\n        assert resp.status_code == 404\n        assert "run_pipeline" in resp.json()["detail"]\n    finally:\n        import shutil\n        shutil.rmtree(empty, ignore_errors=True)\n\n\ndef test_probe_reports_the_current_the_model_advects_with():\n    """The forcing is in m/s. The probe once read it as degrees per hour and\n    showed 9.03 kn for a 0.31 kn current."""\n    import math\n    import numpy as np\n    cid = client.get("/api/incidents").json()[0]["incident_id"]\n    m = client.get(f"/api/incidents/{cid}/manifest").json()\n    f = np.load(m["forcing_path"])\n    b = m["bbox"]\n    r = client.get(f"/api/incidents/{cid}/probe",\n                   params={"lon": (b["min_lon"] + b["max_lon"]) / 2,\n                           "lat": (b["min_lat"] + b["max_lat"]) / 2}).json()\n    speed_ms = math.hypot(float(f["u"]), float(f["v"]))\n    assert abs(r["current"]["speed_knots"] - speed_ms * 1.943844) < 0.001\n    assert abs(r["current"]["speed_km_per_h"] - speed_ms * 3.6) < 0.001\n    bearing = (math.degrees(math.atan2(float(f["u"]), float(f["v"]))) + 360) % 360\n    assert abs(r["current"]["bearing_deg_from_north"] - bearing) < 0.1\n\n\ndef test_overview_serves_each_case_finding_from_its_artifacts():\n    """The overview\'s per-case fields are the artifacts\' own, for every case."""\n    import json, os\n    rows = client.get("/api/overview").json()\n    assert [r["incident_id"] for r in rows] == [r["incident_id"] for r in client.get("/api/incidents").json()]\n    for r in rows:\n        d = os.path.join("data", "cases", r["incident_id"])\n        at = json.load(open(os.path.join(d, "attribution_result.json")))\n        nb = json.load(open(os.path.join(d, "naive_baseline_result.json")))\n        f = r["finding"]\n        assert f["unknown_source"] == at["unknown_source"]\n        assert f["top_candidate_id"] == at["top_candidate_id"]\n        assert f["abstention_iou_gate"] == at["abstention_iou_gate"]\n        assert f["n_candidates"] == len(at["candidates_considered"])\n        assert f["best"]["vessel_key"] == at["ranking"][0]["vessel_key"]\n        assert f["best"]["mean_iou"] == at["ranking"][0]["mean_iou"]\n        assert f["nearest"]["vessel_key"] == nb["ranking"][0]["vessel_key"]\n        assert f["discrimination"] == at["discrimination"]\n'}}
NEW = {'frontend/src/Overview.jsx': 'import { useEffect, useState } from \'react\';\nimport { FAMILY_LABEL } from \'./families\';\nimport { findingHeadline } from \'./findingText\';\nimport \'./overview.css\';\n\n/**\n * Mission control: every case at a glance. Each tile\'s finding is produced by\n * the same rule as the Case Finding card (findingText.js) from the fields\n * /api/overview copies out of each case\'s artifacts - nothing is summarised or\n * written here. The family says what kind of test a case is, never which vessel\n * did it; the status dot is the system\'s own outcome.\n */\nexport default function Overview({ api, onOpen }) {\n  const [rows, setRows] = useState(null);\n  const [error, setError] = useState(null);\n  useEffect(() => {\n    let live = true;\n    api.overview().then((r) => live && setRows(r)).catch((e) => live && setError(String(e.message ?? e)));\n    return () => { live = false; };\n  }, [api]);\n\n  if (error) return <div className="ov"><div className="error-banner">Failed to load the case overview: {error}</div></div>;\n  if (!rows) return <div className="ov"><div className="ov-loading">Loading cases…</div></div>;\n\n  const named = rows.filter((r) => r.finding && !r.finding.unknown_source).length;\n  const abstained = rows.filter((r) => r.finding?.unknown_source).length;\n  return (\n    <div className="ov">\n      <header className="ov-head">\n        <h1>All cases</h1>\n        <p>{rows.length} cases · {named} name a vessel · {abstained} {abstained === 1 ? \'abstains\' : \'abstain\'}</p>\n      </header>\n      <div className="ov-grid">\n        {rows.map((r, i) => {\n          const f = r.finding;\n          const unknown = f?.unknown_source;\n          const differs = f && !unknown && f.nearest && f.best && f.nearest.vessel_key !== f.best.vessel_key;\n          return (\n            <button type="button" key={r.incident_id} className={`ov-tile${unknown ? \' is-abstain\' : \'\'}`}\n                    style={{ \'--k\': i }} onClick={() => onOpen(r.incident_id)}>\n              <span className="ov-top">\n                <span className={`ov-dot${unknown ? \' is-abstain\' : f ? \' is-named\' : \'\'}`} aria-hidden="true" />\n                <span className="ov-id">{r.incident_id.replace(\'_\', \' \')}</span>\n                <span className="ov-family">{FAMILY_LABEL[r.family] ?? r.family}</span>\n              </span>\n              {f ? (\n                <>\n                  <span className="ov-finding">{findingHeadline({ unknown, nCandidates: f.n_candidates, differs })}</span>\n                  <span className="ov-facts">\n                    {unknown\n                      ? <>best fit <b>{f.best?.mean_iou.toFixed(2) ?? \'—\'}</b> · below the gate of {f.abstention_iou_gate}</>\n                      : <>named <b className="mono">{f.best.vessel_key}</b> · mean IoU {f.best.mean_iou.toFixed(2)}\n                          {differs && <> · proximity picked <span className="mono">{f.nearest.vessel_key}</span></>}</>}\n                  </span>\n                </>\n              ) : <span className="ov-finding is-pending">Not yet analysed.</span>}\n              <span className="ov-open">Open case →</span>\n            </button>\n          );\n        })}\n      </div>\n      <p className="ov-foot">Findings are physical consistency under tested assumptions: investigative leads, not proof of\n        responsibility. Every case is synthetic.</p>\n    </div>\n  );\n}\n', 'frontend/src/families.js': "// How each case family is described, shared by the sidebar and the overview.\n// A family says what kind of test a case is, never which vessel did it.\nexport const FAMILY_LABEL = {\n  decoy: 'nearest vessel is a decoy',\n  moving_discharge: 'discharge while under way',\n  absent_source: 'source not in the scene',\n  crowded: 'crowded traffic',\n  along_track_ribbon: 'ribbon laid along track',\n};\n", 'frontend/src/findingText.js': "/**\n * The one-line finding for a case, from its attribution and proximity results.\n * Shared by the Case Finding card and the overview, so both say exactly the\n * same thing: one rule, not two texts to keep in step.\n */\nexport function findingHeadline({ unknown, nCandidates, differs }) {\n  if (unknown) {\n    return `No vessel is named. Forward replay tested ${nCandidates} candidate vessel${nCandidates === 1 ? '' : 's'}, `\n      + 'and none fit the observed slick well enough to reach the gate.';\n  }\n  return differs\n    ? 'The nearest vessel is not supported by forward replay; the best physical fit is another vessel.'\n    : 'The nearest vessel is also the best physical fit under forward replay.';\n}\n", 'frontend/src/overview.css': "/* Mission control: every case as a glass tile. */\n.ov { flex: 1; min-width: 0; height: 100%; overflow-y: auto; padding: var(--space-7) var(--space-7) var(--space-8); }\n.ov-head h1 { font-family: var(--font-display); font-size: 26px; font-weight: 700; letter-spacing: -0.02em; color: var(--label-1); }\n.ov-head p { margin: 4px 0 var(--space-6); font-size: var(--font-size-sm); color: var(--label-2); }\n.ov-loading { color: var(--label-2); font-size: var(--font-size-sm); }\n.ov-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; }\n.ov-tile {\n  position: relative; display: flex; flex-direction: column; gap: 10px; min-height: 176px; padding: 16px 16px 14px;\n  border: 0; border-radius: 14px; text-align: left; font: inherit; color: var(--label-1); cursor: default;\n  background: linear-gradient(160deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.015)), var(--surface-raised);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 6px 20px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.06);\n  opacity: 0; transform: translateY(8px);\n  animation: ov-in 480ms var(--ease-spring) forwards; animation-delay: calc(var(--k) * 45ms);\n  transition: transform var(--dur-base) var(--ease-spring), box-shadow var(--dur-base) ease;\n}\n.ov-tile:hover { transform: translateY(-3px); box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.55), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(10, 132, 255, 0.12); }\n.ov-tile:active { transform: scale(0.985); }\n.ov-tile:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 2px; }\n.ov-tile.is-abstain { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.55), 0 6px 20px rgba(0, 0, 0, 0.12); }\n.ov-tile.is-abstain:hover { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.8), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(255, 159, 10, 0.14); }\n.ov-top { display: flex; align-items: center; gap: 8px; }\n.ov-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--label-3); flex: none; }\n.ov-dot.is-named { background: var(--status-green); box-shadow: 0 0 8px rgba(48, 209, 88, 0.6); }\n.ov-dot.is-abstain { background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.6); }\n.ov-id { font-family: var(--font-mono); font-size: var(--font-size-sm); font-weight: var(--font-weight-semibold); }\n.ov-family { margin-left: auto; padding: 2px 8px; border-radius: 999px; font-size: var(--font-size-xxs); color: var(--label-2);\n             background: var(--fill-pressed); white-space: nowrap; }\n.ov-finding { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-1); }\n.ov-finding.is-pending { color: var(--label-3); }\n.ov-facts { font-size: var(--font-size-xs); color: var(--label-2); }\n.ov-facts b { color: var(--label-1); font-weight: var(--font-weight-semibold); }\n.ov-facts .mono, .ov-facts b.mono { font-family: var(--font-mono); }\n.ov-open { margin-top: auto; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); color: var(--accent);\n           opacity: 0; transform: translateX(-4px); transition: opacity var(--dur-base) ease, transform var(--dur-base) var(--ease-spring); }\n.ov-tile:hover .ov-open, .ov-tile:focus-visible .ov-open { opacity: 1; transform: none; }\n.ov-foot { margin-top: var(--space-6); font-size: var(--font-size-xs); color: var(--label-3); }\n@keyframes ov-in { to { opacity: 1; transform: none; } }\n@media (prefers-reduced-motion: reduce) { .ov-tile { animation: none; opacity: 1; transform: none; } }\n\n/* the sidebar's way back to the overview */\n.nav-overview { display: flex; align-items: center; gap: 9px; width: 100%; margin: 0 0 10px; padding: 8px 12px;\n                border: 0; border-radius: 9px; background: transparent; color: var(--label-1); font: inherit;\n                font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); cursor: default; text-align: left; }\n.nav-overview:hover { background: var(--fill-hover); }\n.nav-overview.is-active { background: var(--accent); color: var(--on-accent); }\n.nav-overview svg { width: 15px; height: 15px; flex: none; }\n"}
README = [('# Comprehensive test suite (337 tests)', '# Comprehensive test suite (338 tests)'), ('- Pytest for comprehensive testing (337 tests covering', '- Pytest for comprehensive testing (338 tests covering')]
CL_OLD = 'correct output": the interface has no ground truth to know that.\n'
CL_NEW = 'correct output": the interface has no ground truth to know that.\n\n**Mission control overview.** A new default view (#/overview) shows every case as a tile:\nits outcome dot, its family, and its one-line finding - produced by the same rule as the\nCase Finding card (findingText.js) from the fields a new /api/overview copies out of each\ncase\'s artifacts, so the two can never say different things. A tile opens its case\n(#/case/<id>); Back and Forward move between them, and an Overview control in the sidebar\nreturns. A test checks the overview\'s fields against every case\'s artifacts.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 27 entry this appends after was not found")
rd = read("README.md"); notes = []
for old, new in README:
    if new in rd: continue
    if rd.count(old) == 1: rd = rd.replace(old, new, 1); notes.append("updated: " + new[:60])
    else: notes.append("NOT FOUND (edit by hand): " + old[:70])
if rd != read("README.md"): writes["README.md"] = rd
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 28: {len(writes)} files written, {skipped} already in place.")
for n in notes: print("  README", n)
